export type OrnamentName = keyof typeof ORNAMENTS;

/** Maps the Colonial Bullets characters stored in content to ornament names. */
export const ORNAMENT_BY_CHAR: Record<string, OrnamentName> = Object.fromEntries(
  Object.entries(ORNAMENTS).map(([name, g]) => [g.glyph.replace('vignette:', ''), name as OrnamentName]),
);

/** Inline ornament sized like a glyph of the surrounding font size (1em = font size). */
export function Ornament({ name, className, style }: { name: OrnamentName; className?: string; style?: CSSProperties }) {
  const g: Glyph = ORNAMENTS[name];
  const height = (g.asc - g.desc) / g.upm;
  return (
    <svg
      className={['ornament', className].filter(Boolean).join(' ')}
      viewBox={`${g.x} ${-g.asc} ${g.w} ${g.asc - g.desc}`}
      style={{ width: `${g.w / g.upm}em`, height: `${height}em`, verticalAlign: `${g.desc / g.upm}em`, ...style }}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
    >
      <path transform="scale(1,-1)" d={g.d} />
    </svg>
  );
}
